"use client";

import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useState } from "react";
import ProductBrandLogo from "./product-brand-logo";
import { apiFetch } from "./supabase-browser";

type Permission = "view_revenue" | "view_profit" | "view_banking" | "view_payroll" | "create_transactions" | "edit_drafts" | "post_journals" | "approve_bills" | "initiate_payments" | "reconcile_accounts" | "change_tax_settings" | "lock_periods" | "unlock_periods" | "export_data" | "manage_integrations" | "view_audit_logs";
type Section = typeof sectionDefinitions[number]["name"];
type TaskSeed = { title: string; detail: string; priority: "high" | "medium" | "low"; expectedImpact?: string; sourceType?: "alert"; sourceRef?: string };

const sectionDefinitions = [
  { name: "Overview", group: "Command", permission: "view_profit" },
  { name: "Transactions", group: "Command", permission: "view_profit" },
  { name: "Banking", group: "Cash", permission: "view_banking" },
  { name: "Reconciliation", group: "Cash", permission: "reconcile_accounts" },
  { name: "Sales", group: "Money in", permission: "view_revenue" },
  { name: "Expenses", group: "Money out", permission: "view_profit" },
  { name: "Bills", group: "Money out", permission: "view_profit" },
  { name: "Invoicing", group: "Money in", permission: "view_revenue" },
  { name: "Customers", group: "Records", permission: "view_revenue" },
  { name: "Suppliers", group: "Records", permission: "view_profit" },
  { name: "Chart of Accounts", group: "Accounting", permission: "view_profit" },
  { name: "Journal Entries", group: "Accounting", permission: "post_journals" },
  { name: "Payroll", group: "Accounting", permission: "view_payroll" },
  { name: "Sales Tax", group: "Accounting", permission: "view_profit" },
  { name: "Inventory Accounting", group: "Accounting", permission: "view_profit" },
  { name: "Assets and Loans", group: "Planning", permission: "view_profit" },
  { name: "Budgets", group: "Planning", permission: "view_profit" },
  { name: "Cash Flow", group: "Planning", permission: "view_banking" },
  { name: "Reports", group: "Close and review", permission: "view_profit" },
  { name: "Month-End", group: "Close and review", permission: "reconcile_accounts" },
  { name: "Accountant Portal", group: "Close and review", permission: "view_audit_logs" },
  { name: "Audit Trail", group: "Close and review", permission: "view_audit_logs" },
  { name: "BookLoQ Assistant", group: "Tools", permission: "view_profit" },
  { name: "Settings", group: "Tools", permission: "manage_integrations" },
] as const satisfies readonly { name: string; group: string; permission: Permission }[];

type Account = { id: string; code: string; name: string; accountType: "asset" | "liability" | "equity" | "revenue" | "expense"; accountSubtype: string; normalBalance: "debit" | "credit"; systemKey: string | null; description: string; plainLanguage: string; debitCents: number; creditCents: number; balanceCents: number };
type Transaction = { id: string; transactionDate: string; postingDate: string; description: string; originalDescription: string; amountCents: number; currency: string; taxAmountCents: number; sourceSystem: string; externalSourceId: string; locationRef: string; reconciliationStatus: string; categorizationStatus: string; confidenceBasisPoints: number; approvalStatus: string; demoRecord: number; accountCode: string | null; accountName: string | null; contactName: string | null };
type Bank = { id: string; name: string; accountType: string; institutionName: string; maskedNumber: string; liveBalanceCents: number | null; availableBalanceCents: number | null; bookBalanceCents: number; availableCreditCents: number | null; connectionStatus: string; lastSyncAt: number | null; lastReconciledAt: number | null; demoRecord: number; accountCode: string; accountName: string };
type Reconciliation = { id: string; reconciliationType: string; startDate: string; endDate: string; openingBalanceCents: number; closingBalanceCents: number; bookBalanceCents: number; differenceCents: number; status: string; accountCode: string; accountName: string };
type Bill = { id: string; billNumber: string; invoiceDate: string; dueDate: string; status: string; subtotalCents: number; taxCents: number; totalCents: number; paidCents: number; currency: string; purchaseOrderRef: string | null; approvalStatus: string; demoRecord: number; supplierName: string };
type Invoice = { id: string; invoiceNumber: string; invoiceDate: string; dueDate: string; status: string; subtotalCents: number; taxCents: number; totalCents: number; paidCents: number; currency: string; demoRecord: number; customerName: string };
type Contact = { id: string; contactType: "customer" | "supplier" | "both"; name: string; email: string; phone: string; billingAddress: string; paymentTermsDays: number; creditLimitCents: number; notes: string; active: number };
type Alert = { id: string; severity: "critical" | "attention" | "opportunity" | "informational"; alertType: string; title: string; explanation: string; dollarImpactCents: number | null; confidence: "high" | "medium" | "low"; supportingRecordsJson: string; recommendedAction: string; dueDate: string | null; status: string; resolutionHistoryJson: string; demoRecord: number; createdAt: number };
type Journal = { id: string; entryNumber: string; entryDate: string; postingDate: string; status: string; sourceType: string; sourceRef: string | null; memo: string; currency: string; totalDebitCents: number; totalCreditCents: number; reversalOfEntryId: string | null; postedAt: number | null; lineCount: number };
type Period = { id: string; label: string; startDate: string; endDate: string; status: string; lockedAt: number | null };
type CloseItem = { id: string; periodId: string; itemKey: string; title: string; status: "not_started" | "in_progress" | "blocked" | "complete"; dueDate: string | null; blocker: string; completedAt: number | null };
type Budget = { id: string; periodStart: string; periodEnd: string; locationRef: string; departmentRef: string; budgetCents: number; committedCents: number; forecastCents: number; accountCode: string; accountName: string; accountType: string };
type Audit = { action: string; resourceType: string; resourceId: string | null; outcome: string; detailsJson: string; createdAt: number };
type Summary = { currentCashCents: number; availableCashCents: number; bankBalanceCents: number | null; bookBalanceCents: number; revenueCents: number; grossProfitCents: number; grossMarginBasisPoints: number | null; operatingProfitCents: number; totalExpensesCents: number; accountsReceivableCents: number; accountsPayableCents: number; salesTaxPayableCents: number; payrollObligationsCents: number; debtObligationsCents: number; upcomingBillsCount: number; overdueInvoicesCount: number; unreconciledCount: number; uncategorizedCount: number; missingReceiptsCount: number; monthEndCompletionRate: number; healthScore: number };
type BookLoQData = { configured: boolean; settings: null | { baseCurrency: string; countryCode: string; provinceCode: string; accountingBasis: string; cashSafetyThresholdCents: number; status: string; dataMode: "live" | "demonstration" }; role: string; permissions: Permission[]; organization: { name: string; currency: string }; summary: Summary; statements: { accounts: Account[]; trialBalance: { totalDebitCents: number; totalCreditCents: number }; profitAndLoss: { revenueCents: number; expenseCents: number; cogsCents: number; grossProfitCents: number; operatingProfitCents: number }; balanceSheet: { assetCents: number; liabilityCents: number; equityCents: number }; cashCents: number; accountsReceivableCents: number; accountsPayableCents: number; netSalesTaxCents: number }; forecasts: { days: number; endDate: string; confirmedNetCents: number; probableNetCents: number; estimatedNetCents: number; closingCashCents: number }[]; cashIntelligence: { status: "available" | "unavailable"; liquidity30Cents: number | null; liquidity60Cents: number | null; purchasingCapacityCents: number | null; risk: "low" | "moderate" | "high" | "unavailable"; minimumCashCents: number | null; minimumCashDate: string | null; warning: string | null; evidence: string[] }; transactions: Transaction[]; banks: Bank[]; reconciliations: Reconciliation[]; bills: Bill[]; invoices: Invoice[]; contacts: Contact[]; alerts: Alert[]; journals: Journal[]; periods: Period[]; closeItems: CloseItem[]; budgets: Budget[]; audit: Audit[]; integrations: Record<string, string>; disclaimer: string };

const money = (value: number | null | undefined, currency = "CAD") => value == null ? "Not connected" : new Intl.NumberFormat("en-CA", { style: "currency", currency, minimumFractionDigits: 0, maximumFractionDigits: 2 }).format(value / 100);
const rate = (basisPoints: number | null | undefined) => basisPoints == null ? "Not available" : `${(basisPoints / 100).toFixed(1)}%`;
const shortDate = (value: string) => new Intl.DateTimeFormat("en-CA", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }).format(new Date(`${value}T00:00:00Z`));
const label = (value: string) => value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const parseJsonList = (value: string) => { try { const parsed: unknown = JSON.parse(value); return Array.isArray(parsed) ? parsed.map(String) : []; } catch { return []; } };

export default function BookLoQWorkspace({ createTask, showNotice }: { createTask: (seed: TaskSeed) => void; showNotice: (message: string) => void }) {
  const [data, setData] = useState<BookLoQData | null>(null);
  const [section, setSection] = useState<Section>("Overview");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [navSearch, setNavSearch] = useState("");
  const [collapsed, setCollapsed] = useState(false);
  const [journalOpen, setJournalOpen] = useState(false);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const response = await apiFetch("/api/v1/bookloq", { headers: { Accept: "application/json" } });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error?.message ?? "BookLoQ could not be loaded.");
      setData(body.bookloq); setError("");
    } catch (caught) { setError(caught instanceof Error ? caught.message : "BookLoQ could not be loaded."); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { const timer = window.setTimeout(() => void refresh(), 0); return () => window.clearTimeout(timer); }, [refresh]);

  const visible = useMemo(() => sectionDefinitions.filter((item) => data?.permissions.includes(item.permission) && item.name.toLowerCase().includes(navSearch.toLowerCase())), [data, navSearch]);
  const activeSection = visible.some((item) => item.name === section) ? section : (visible[0]?.name ?? "Overview");

  if (loading) return <div className="bookloq-loading"><ProductBrandLogo product="bookloq"/><b>Preparing BookLoQ</b><small>Validating ledger access and financial sources…</small></div>;
  if (error) return <div className="bookloq-loading error"><span>!</span><b>BookLoQ needs attention</b><small>{error}</small><button onClick={refresh}>Try again</button></div>;
  if (!data) return null;
  if (!data.configured) return <BookLoQStart/>;

  return <div className={`bookloq-shell ${collapsed ? "bookloq-collapsed" : ""}`}>
    <aside className="bookloq-side">
      <div className="bookloq-brand"><ProductBrandLogo product="bookloq"/><span><b>BookLoQ</b><small>ACCOUNTING</small></span><button aria-label={collapsed ? "Expand BookLoQ navigation" : "Collapse BookLoQ navigation"} onClick={() => setCollapsed((value) => !value)}>‹</button></div>
      {!collapsed && <><label className="bookloq-search"><span>⌕</span><input aria-label="Search BookLoQ navigation" value={navSearch} onChange={(event) => setNavSearch(event.target.value)} placeholder="Find a finance workspace"/></label><nav aria-label="BookLoQ navigation">{[...new Set(visible.map((item) => item.group))].map((group) => <section key={group}><p>{group}</p>{visible.filter((item) => item.group === group).map((item) => <button key={item.name} className={activeSection === item.name ? "active" : ""} onClick={() => setSection(item.name)}><span>{sectionIcon(item.name)}</span>{item.name}</button>)}</section>)}</nav></>}
      <div className="bookloq-side-foot"><i className={data.settings?.dataMode === "demonstration" ? "demo" : "live"}/>{!collapsed && <span><b>{data.settings?.dataMode === "demonstration" ? "Demonstration data" : "Live ledger"}</b><small>{data.organization.currency} · {data.settings?.accountingBasis}</small></span>}</div>
    </aside>
    <main className="bookloq-main">
      <header className="bookloq-top"><div><p>VANTELOQ / BOOKLOQ</p><h2>{activeSection}</h2></div><div><span className="bookloq-health"><i style={{ "--health": `${data.summary.healthScore * 3.6}deg` } as React.CSSProperties}/><b>{data.summary.healthScore}</b><small>BOOKS HEALTH</small></span>{data.permissions.includes("post_journals") && <button className="bookloq-primary" onClick={() => setJournalOpen(true)}>+ Journal entry</button>}</div></header>
      {data.settings?.dataMode === "demonstration" && <div className="bookloq-demo-banner"><b>Demonstration workspace</b><span>Every figure below is clearly separated from live Vanteloq and exists only to evaluate BookLoQ workflows.</span></div>}
      <BookLoQSection section={activeSection} data={data} setSection={setSection} createTask={createTask} showNotice={showNotice} refresh={refresh} openJournal={() => setJournalOpen(true)}/>
    </main>
    {journalOpen && <JournalComposer data={data} close={() => setJournalOpen(false)} saved={async () => { setJournalOpen(false); await refresh(); showNotice("Balanced journal posted and added to the audit trail"); }}/>} 
  </div>;
}

function BookLoQStart() {
  return <div className="bookloq-start"><ProductBrandLogo product="bookloq" variant="full"/><p>VANTELOQ FINANCIAL CONTROL</p><h2>BookLoQ keeps your books organized, explains your financial position and shows you what requires attention.</h2><span>No verified financial records have been added. Balances, reports, liquidity and tax figures remain unavailable until a source is connected.</span><div><button disabled title="Secure bank and POS connections are not available yet.">Connect live financial data</button></div><small>BookLoQ never substitutes demonstration balances for missing records. Banking, POS, payroll, receipt capture, payments and tax filing stay off until their connections are verified.</small></div>;
}

function BookLoQSection(props: { section: Section; data: BookLoQData; setSection: (section: Section) => void; createTask: (seed: TaskSeed) => void; showNotice: (message: string) => void; refresh: () => Promise<void>; openJournal: () => void }) {
  const { section } = props;
  if (section === "Overview") return <OverviewPanel {...props}/>;
  if (section === "Transactions") return <TransactionCentre data={props.data}/>;
  if (section === "Banking" || section === "Reconciliation") return <BankingPanel data={props.data} reconciliation={section === "Reconciliation"}/>;
  if (section === "Sales" || section === "Invoicing") return <ReceivablesPanel data={props.data}/>;
  if (section === "Expenses") return <ExpensesPanel data={props.data}/>;
  if (section === "Bills") return <BillsPanel data={props.data}/>;
  if (section === "Customers" || section === "Suppliers") return <ContactsPanel data={props.data} type={section === "Customers" ? "customer" : "supplier"}/>;
  if (section === "Chart of Accounts") return <AccountsPanel data={props.data}/>;
  if (section === "Journal Entries") return <JournalsPanel data={props.data} openJournal={props.openJournal} refresh={props.refresh} showNotice={props.showNotice}/>;
  if (section === "Payroll") return <PayrollPanel data={props.data}/>;
  if (section === "Sales Tax") return <TaxPanel data={props.data}/>;
  if (section === "Inventory Accounting") return <InventoryPanel data={props.data}/>;
  if (section === "Assets and Loans") return <AssetsPanel data={props.data}/>;
  if (section === "Budgets") return <BudgetPanel data={props.data}/>;
  if (section === "Cash Flow") return <CashFlowPanel data={props.data}/>;
  if (section === "Reports") return <ReportsPanel data={props.data}/>;
  if (section === "Month-End") return <MonthEndPanel data={props.data} refresh={props.refresh} showNotice={props.showNotice}/>;
  if (section === "Accountant Portal") return <AccountantPanel data={props.data}/>;
  if (section === "Audit Trail") return <AuditPanel data={props.data}/>;
  if (section === "BookLoQ Assistant") return <AssistantPanel data={props.data} createTask={props.createTask}/>;
  return <SettingsPanel data={props.data}/>;
}

function OverviewPanel({ data, setSection, createTask, refresh, showNotice }: { data: BookLoQData; setSection: (section: Section) => void; createTask: (seed: TaskSeed) => void; refresh: () => Promise<void>; showNotice: (message: string) => void }) {
  const s = data.summary;
  const openAlerts = data.alerts.filter((alert) => alert.status === "open");
  return <div className="bookloq-content">
    <section className="bookloq-promise"><div><p>30-SECOND FINANCIAL POSITION</p><h3>{openAlerts[0]?.title ?? "No open financial exception is currently prioritized."}</h3><span>{openAlerts[0]?.explanation ?? "BookLoQ found no active alert in the connected records."}</span></div>{openAlerts[0] && <button onClick={() => createTask(alertTask(openAlerts[0], data.organization.currency))}>Turn into Vanteloq task →</button>}</section>
    <section className="bookloq-kpis">
      <FinancialKpi label="Current cash" value={money(s.currentCashCents)} note="Posted ledger balance" onClick={() => setSection("Banking")}/>
      <FinancialKpi label="Available cash" value={money(s.availableCashCents)} note="Cash less confirmed 30-day bills" onClick={() => setSection("Cash Flow")}/>
      <FinancialKpi label="Revenue" value={money(s.revenueCents)} note="Posted revenue accounts" onClick={() => setSection("Sales")}/>
      <FinancialKpi label="Gross profit" value={money(s.grossProfitCents)} note={`${rate(s.grossMarginBasisPoints)} gross margin`} onClick={() => setSection("Reports")}/>
      <FinancialKpi label="Operating profit" value={money(s.operatingProfitCents)} note="Revenue less posted expenses" onClick={() => setSection("Reports")}/>
      <FinancialKpi label="Total expenses" value={money(s.totalExpensesCents)} note="Including cost of goods sold" onClick={() => setSection("Expenses")}/>
      <FinancialKpi label="Receivable" value={money(s.accountsReceivableCents)} note={`${s.overdueInvoicesCount} overdue invoices`} onClick={() => setSection("Invoicing")}/>
      <FinancialKpi label="Payable" value={money(s.accountsPayableCents)} note={`${s.upcomingBillsCount} open bills`} onClick={() => setSection("Bills")}/>
      <FinancialKpi label="GST position" value={money(s.salesTaxPayableCents)} note="Collected less recoverable" onClick={() => setSection("Sales Tax")}/>
      <FinancialKpi label="Debt" value={money(s.debtObligationsCents)} note="Posted principal balance" onClick={() => setSection("Assets and Loans")}/>
      <FinancialKpi label="Unreconciled" value={String(s.unreconciledCount)} note={`${s.uncategorizedCount} require category review`} onClick={() => setSection("Transactions")}/>
      <FinancialKpi label="Month-end" value={`${Math.round(s.monthEndCompletionRate * 100)}%`} note="Checklist completion" onClick={() => setSection("Month-End")}/>
    </section>
    <section className="bookloq-two">
      <article className="bookloq-card bookloq-attention"><Header kicker="FINANCIAL ATTENTION CENTRE" title="What requires action" action={<button onClick={() => setSection("Transactions")}>Open transaction centre</button>}/>{openAlerts.length ? openAlerts.slice(0, 4).map((alert) => <AlertRow key={alert.id} alert={alert} currency={data.organization.currency} createTask={createTask} refresh={refresh} showNotice={showNotice}/>) : <EmptyLine text="No open alerts were produced by the current records."/>}</article>
      <article className="bookloq-card"><Header kicker="CASH OUTLOOK" title="Confirmed and probable cash movement" action={<button onClick={() => setSection("Cash Flow")}>Open forecast</button>}/><div className="forecast-list">{data.forecasts.map((item) => <div key={item.days}><span><b>{item.days === 365 ? "12 months" : `${item.days} days`}</b><small>through {shortDate(item.endDate)}</small></span><strong className={item.closingCashCents < 0 ? "negative" : ""}>{money(item.closingCashCents)}</strong><i style={{ width: `${Math.min(100, Math.max(8, Math.abs(item.closingCashCents) / Math.max(1, Math.abs(data.summary.currentCashCents)) * 70))}%` }}/></div>)}</div><small className="calculation-note">Closing cash = posted cash + confirmed bills + probable receivables. Estimates remain separate.</small></article>
    </section>
    <section className="bookloq-card bookloq-integrity"><Header kicker="CONTROL STATUS" title="What BookLoQ knows and what it does not"/><div><Integrity label="Double-entry ledger" status={data.statements.trialBalance.totalDebitCents === data.statements.trialBalance.totalCreditCents ? "Verified" : "Issue"} detail={`${money(data.statements.trialBalance.totalDebitCents)} debits · ${money(data.statements.trialBalance.totalCreditCents)} credits`}/><Integrity label="Bank feed" status="Not connected" detail="Demonstration balance only; no banking credentials are stored."/><Integrity label="Tax filing" status="Not connected" detail="Working-paper assistance only. No filing is represented as submitted."/><Integrity label="Receipt capture" status="Not connected" detail="OCR and file scanning remain disabled until private document storage is configured."/></div></section>
  </div>;
}

function FinancialKpi({ label: name, value, note, onClick }: { label: string; value: string; note: string; onClick?: () => void }) {
  const content = <><span>{name}{onClick && <i>↗</i>}</span><b>{value}</b><small>{note}</small></>;
  return onClick
    ? <button type="button" className="bookloq-kpi" onClick={onClick}>{content}</button>
    : <article className="bookloq-kpi static">{content}</article>;
}
function Header({ kicker, title, action }: { kicker: string; title: string; action?: ReactNode }) { return <div className="bookloq-card-head"><div><p>{kicker}</p><h3>{title}</h3></div>{action}</div>; }
function EmptyLine({ text }: { text: string }) { return <div className="bookloq-empty-line"><span>✓</span>{text}</div>; }
function Integrity({ label: name, status, detail }: { label: string; status: string; detail: string }) { return <article><span className={status === "Verified" ? "ok" : status === "Issue" ? "issue" : "off"}>{status}</span><div><b>{name}</b><small>{detail}</small></div></article>; }

function alertTask(alert: Alert, currency: string): TaskSeed { return { title: alert.title, detail: `${alert.explanation} Recommended action: ${alert.recommendedAction}`, priority: alert.severity === "critical" ? "high" : alert.severity === "attention" ? "medium" : "low", expectedImpact: alert.dollarImpactCents == null ? "Impact requires review" : money(alert.dollarImpactCents, currency), sourceType: "alert", sourceRef: alert.id }; }

function AlertRow({ alert, currency, createTask, refresh, showNotice }: { alert: Alert; currency: string; createTask: (seed: TaskSeed) => void; refresh: () => Promise<void>; showNotice: (message: string) => void }) {
  const change = async (status: string) => { const response = await apiFetch("/api/v1/bookloq/actions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type: "alert_status", alertId: alert.id, status }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error?.message ?? "Alert could not be updated."); await refresh(); showNotice("Financial alert status updated"); };
  return <div className={`bookloq-alert ${alert.severity}`}><span className="bookloq-alert-mark">{alert.severity === "critical" ? "!" : alert.severity === "opportunity" ? "↗" : "•"}</span><div><small>{label(alert.severity)} · {alert.confidence} confidence</small><b>{alert.title}</b><p>{alert.explanation}</p><em>Recommended: {alert.recommendedAction}</em><span className="supporting">Supports: {parseJsonList(alert.supportingRecordsJson).join(" · ")}</span></div><aside><strong>{money(alert.dollarImpactCents, currency)}</strong><button onClick={() => createTask(alertTask(alert, currency))}>Create task</button><select aria-label={`Status for ${alert.title}`} value={alert.status} onChange={(event) => void change(event.target.value)}><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select></aside></div>;
}

function TransactionCentre({ data }: { data: BookLoQData }) {
  const [query, setQuery] = useState(""); const [review, setReview] = useState("all"); const [selected, setSelected] = useState<Transaction | null>(null);
  const filtered = data.transactions.filter((transaction) => `${transaction.description} ${transaction.originalDescription} ${transaction.contactName ?? ""} ${transaction.accountName ?? ""}`.toLowerCase().includes(query.toLowerCase()) && (review === "all" || transaction.categorizationStatus === review || transaction.reconciliationStatus === review));
  return <div className="bookloq-content"><PageIntro eyebrow="UNIFIED TRANSACTION CENTRE" title="Every financial record, one review queue" copy="Bank, POS, processor, bill, invoice, payroll and owner activity appear together only when supported by a stored source record."/>
    <div className="bookloq-toolbar"><label><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search description, supplier, account or source"/></label><select value={review} onChange={(event) => setReview(event.target.value)}><option value="all">All review states</option><option value="confirmed">Automatically confirmed</option><option value="suggested">Suggested for review</option><option value="missing">Missing information</option><option value="issue">Potential issue</option><option value="accountant_review">Accountant review required</option><option value="unreconciled">Unreconciled</option></select><button onClick={() => downloadTransactions(filtered)}>Export CSV</button></div>
    <article className="bookloq-card bookloq-table-card"><div className="bookloq-table"><div className="bookloq-tr bookloq-th"><span>Date</span><span>Description</span><span>Source</span><span>Account</span><span>Review state</span><span>Amount</span></div>{filtered.map((transaction) => <button className="bookloq-tr" key={transaction.id} onClick={() => setSelected(transaction)}><span>{shortDate(transaction.postingDate)}</span><span><b>{transaction.description}</b><small>{transaction.contactName ?? transaction.originalDescription}</small></span><span>{label(transaction.sourceSystem)}</span><span>{transaction.accountCode ? `${transaction.accountCode} · ${transaction.accountName}` : "Uncategorized"}</span><span><i className={`state ${transaction.categorizationStatus}`}>{label(transaction.categorizationStatus)}</i><small>{Math.round(transaction.confidenceBasisPoints / 100)}% confidence</small></span><span className={transaction.amountCents < 0 ? "negative" : "positive"}>{money(transaction.amountCents, transaction.currency)}</span></button>)}</div>{!filtered.length && <EmptyLine text="No transaction matches this view."/>}</article>
    {selected && <RecordDrawer title={selected.description} close={() => setSelected(null)} rows={[["Original description", selected.originalDescription], ["Posting date", selected.postingDate], ["Source system", selected.sourceSystem], ["External source ID", selected.externalSourceId], ["Account", selected.accountName ?? "Missing"], ["Location", selected.locationRef], ["Reconciliation", label(selected.reconciliationStatus)], ["Categorization", label(selected.categorizationStatus)], ["Confidence", `${Math.round(selected.confidenceBasisPoints / 100)}%`], ["Amount", money(selected.amountCents, selected.currency)]]}/>} 
  </div>;
}

function BankingPanel({ data, reconciliation }: { data: BookLoQData; reconciliation: boolean }) {
  const gross = data.transactions.filter((item) => item.sourceSystem.includes("lightspeed") && item.amountCents > 0).reduce((sum, item) => sum + item.amountCents, 0);
  const payout = data.transactions.filter((item) => item.sourceSystem.includes("moneris") && item.amountCents > 0).reduce((sum, item) => sum + item.amountCents, 0);
  const fees = Math.abs(data.transactions.filter((item) => item.sourceSystem.includes("moneris") && item.amountCents < 0).reduce((sum, item) => sum + item.amountCents, 0));
  return <div className="bookloq-content"><PageIntro eyebrow={reconciliation ? "RECONCILIATION CENTRE" : "BANKING"} title={reconciliation ? "Make every source agree before close" : "Bank position with book-level evidence"} copy="Balances are never treated as live unless a verified financial-data connection confirms them."/>
    {!reconciliation && <section className="bank-grid">{data.banks.map((bank) => <article className="bookloq-card" key={bank.id}><div className="bank-logo">▤</div><span><b>{bank.name}</b><small>{bank.institutionName} · {bank.maskedNumber}</small></span><strong>{money(bank.liveBalanceCents)}</strong><div><small>Book balance <b>{money(bank.bookBalanceCents)}</b></small><small>Difference <b className={(bank.liveBalanceCents ?? bank.bookBalanceCents) - bank.bookBalanceCents !== 0 ? "negative" : ""}>{money((bank.liveBalanceCents ?? bank.bookBalanceCents) - bank.bookBalanceCents)}</b></small></div><em>{bank.demoRecord ? "Demonstration connection" : label(bank.connectionStatus)}</em></article>)}</section>}
    <section className="bookloq-two"><article className="bookloq-card"><Header kicker="POS PAYOUT BRIDGE" title="From gross sales to bank deposit"/><div className="bridge"><Line label="Gross card sales" value={gross}/><Line label="Processing fees" value={-fees}/><Line label="Expected deposit" value={gross - fees} total/><Line label="Recorded processor payout" value={payout}/><Line label="Payout difference" value={payout - (gross - fees)} total/></div><small className="calculation-note">Each component comes from the labelled POS and processor transactions shown in the transaction centre.</small></article><article className="bookloq-card"><Header kicker="ACCOUNT RECONCILIATIONS" title="Opening, closing and book balance"/><div className="reconciliation-list">{data.reconciliations.map((item) => <div key={item.id}><span><b>{item.accountName}</b><small>{shortDate(item.startDate)}–{shortDate(item.endDate)} · {label(item.status)}</small></span><span><small>Statement</small><b>{money(item.closingBalanceCents)}</b></span><span><small>Books</small><b>{money(item.bookBalanceCents)}</b></span><strong className={item.differenceCents ? "negative" : "positive"}>{money(item.differenceCents)}</strong></div>)}</div></article></section>
    <ProviderGate title="Secure bank connection" detail="Live banking remains disabled. BookLoQ never stores online-banking credentials; a supported financial-data provider must complete authorization, token handling, replay protection and recovery first."/>
  </div>;
}

function ReceivablesPanel({ data }: { data: BookLoQData }) { const today = new Date().toISOString().slice(0, 10); return <div className="bookloq-content"><PageIntro eyebrow="SALES AND ACCOUNTS RECEIVABLE" title="Know what was earned and what remains collectible" copy="Invoice states, aging and journal-backed revenue stay connected to the same customer record."/><section className="bookloq-kpis compact"><FinancialKpi label="Posted revenue" value={money(data.summary.revenueCents)} note="Revenue accounts"/><FinancialKpi label="Outstanding A/R" value={money(data.summary.accountsReceivableCents)} note="Posted receivable balance"/><FinancialKpi label="Overdue" value={String(data.invoices.filter((invoice) => invoice.dueDate < today && invoice.status !== "paid").length)} note="Past due date"/></section><DataTable headings={["Invoice", "Customer", "Issued", "Due", "State", "Outstanding"]} rows={data.invoices.map((invoice) => [invoice.invoiceNumber, invoice.customerName, shortDate(invoice.invoiceDate), shortDate(invoice.dueDate), label(invoice.status), money(invoice.totalCents - invoice.paidCents, invoice.currency)])}/><ProviderGate title="Payment links and reminder delivery" detail="Reminder drafts and online payment links require verified email and payment-provider connections. Nothing will be sent or charged without an authorized user’s approval."/></div>; }
function ExpensesPanel({ data }: { data: BookLoQData }) { const expenses = data.statements.accounts.filter((account) => account.accountType === "expense").sort((a, b) => b.balanceCents - a.balanceCents); return <div className="bookloq-content"><PageIntro eyebrow="EXPENSE MANAGEMENT" title="See where money went and which cost changed profit" copy="Posted ledger balances are separated from bills, committed spend and transactions awaiting categorization."/><DataTable headings={["Account", "Plain-language purpose", "Posted amount", "Share of expense"]} rows={expenses.map((account) => [`${account.code} · ${account.name}`, account.plainLanguage, money(account.balanceCents), data.summary.totalExpensesCents ? rate(Math.round(account.balanceCents * 10_000 / data.summary.totalExpensesCents)) : "—"])}/><ProviderGate title="Receipt and invoice capture" detail="Camera, email forwarding, OCR and supplier-portal upload remain disabled until private object storage, malware scanning, signed uploads and review confidence are configured."/></div>; }
function BillsPanel({ data }: { data: BookLoQData }) { return <div className="bookloq-content"><PageIntro eyebrow="BILLS AND ACCOUNTS PAYABLE" title="Control what is owed before cash leaves" copy="No payment is initiated from this workspace. Approval state and supporting records must be complete first."/><DataTable headings={["Bill", "Supplier", "Due", "Workflow state", "Approval", "Outstanding"]} rows={data.bills.map((bill) => [bill.billNumber, bill.supplierName, shortDate(bill.dueDate), label(bill.status), label(bill.approvalStatus), money(bill.totalCents - bill.paidCents, bill.currency)])}/><ProviderGate title="Payments are approval-gated" detail="Real bill payment is intentionally unavailable until a regulated provider, recent reauthentication, dual approval, limits, callbacks and reconciliation are implemented."/></div>; }
function ContactsPanel({ data, type }: { data: BookLoQData; type: "customer" | "supplier" }) { const contacts = data.contacts.filter((contact) => contact.contactType === type || contact.contactType === "both"); return <div className="bookloq-content"><PageIntro eyebrow={type === "customer" ? "CUSTOMER RECORDS" : "SUPPLIER RECORDS"} title={type === "customer" ? "Receivables with customer context" : "Payables with supplier context"} copy="BookLoQ shares source-of-truth contacts with Vanteloq instead of duplicating operational records."/><div className="contact-grid">{contacts.map((contact) => <article className="bookloq-card" key={contact.id}><span className="contact-avatar">{contact.name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2)}</span><div><b>{contact.name}</b><small>{contact.email}</small></div><dl><dt>Terms</dt><dd>{contact.paymentTermsDays} days</dd><dt>Credit limit</dt><dd>{money(contact.creditLimitCents)}</dd><dt>Context</dt><dd>{contact.notes}</dd></dl></article>)}</div>{!contacts.length && <EmptyLine text={`No ${type} records exist in this ledger.`}/>}</div>; }
function AccountsPanel({ data }: { data: BookLoQData }) { return <div className="bookloq-content"><PageIntro eyebrow="CHART OF ACCOUNTS" title="Accountant-grade structure, explained plainly" copy="Accounts with posted history can be archived but are never silently deleted."/><DataTable headings={["Code", "Account", "Type", "Normal balance", "Plain-language explanation", "Balance"]} rows={data.statements.accounts.map((account) => [account.code, account.name, label(account.accountType), label(account.normalBalance), account.plainLanguage, money(account.balanceCents)])}/></div>; }

function JournalsPanel({ data, openJournal, refresh, showNotice }: { data: BookLoQData; openJournal: () => void; refresh: () => Promise<void>; showNotice: (message: string) => void }) {
  const reverse = async (entry: Journal) => { const reason = window.prompt(`Reason for reversing ${entry.entryNumber}`); if (!reason) return; const response = await apiFetch("/api/v1/bookloq/journals", { method: "PATCH", headers: { "Content-Type": "application/json", "Idempotency-Key": crypto.randomUUID() }, body: JSON.stringify({ entryId: entry.id, reason, reversalDate: new Date().toISOString().slice(0, 10) }) }); const body = await response.json(); if (!response.ok) { showNotice(body.error?.message ?? "Journal could not be reversed"); return; } await refresh(); showNotice("Reversal posted; the original entry remains in history"); };
  return <div className="bookloq-content"><PageIntro eyebrow="GENERAL JOURNAL" title="Balanced entries with an immutable correction path" copy="Posted entries are corrected by reversal or adjustment; they are never silently overwritten." action={<button className="bookloq-primary" onClick={openJournal}>+ New journal</button>}/><DataTable headings={["Entry", "Date", "Explanation", "Source", "Lines", "Debits / credits", "Status", "Correction"]} rows={data.journals.map((entry) => [entry.entryNumber, shortDate(entry.postingDate), entry.memo, label(entry.sourceType), String(entry.lineCount), `${money(entry.totalDebitCents)} / ${money(entry.totalCreditCents)}`, label(entry.status), entry.status === "posted" && entry.sourceType !== "reversal" ? <button className="table-action" onClick={() => void reverse(entry)}>Reverse</button> : "—"])}/></div>;
}

function PayrollPanel({ data }: { data: BookLoQData }) { const wages = data.statements.accounts.find((account) => account.systemKey === "wage_expense")?.balanceCents ?? 0; return <div className="bookloq-content"><PageIntro eyebrow="PAYROLL ACCOUNTING" title="Reconcile payroll cost without replacing payroll" copy="BookLoQ initially accepts verified payroll journals and compares them with bank withdrawals."/><section className="bookloq-kpis compact"><FinancialKpi label="Posted wage expense" value={money(wages)} note="General ledger"/><FinancialKpi label="Payroll liabilities" value={money(data.summary.payrollObligationsCents)} note="Amounts still payable"/></section><ProviderGate title="External payroll provider required" detail="Employee deductions, remittances and pay runs are not calculated here. Connect an approved payroll provider before using BookLoQ with real payroll data."/></div>; }
function TaxPanel({ data }: { data: BookLoQData }) { const collected = data.statements.accounts.find((account) => account.systemKey === "gst_collected")?.balanceCents ?? 0; const recoverable = data.statements.accounts.find((account) => account.systemKey === "gst_recoverable")?.balanceCents ?? 0; return <div className="bookloq-content"><PageIntro eyebrow="CANADIAN SALES TAX" title="GST/HST working position with supporting balances" copy="This is preparation support, not a representation that a return was filed."/><section className="bookloq-kpis compact"><FinancialKpi label="Tax collected" value={money(collected)} note="Posted GST collected account"/><FinancialKpi label="Recoverable tax" value={money(recoverable)} note="Potential input tax credits"/><FinancialKpi label={data.summary.salesTaxPayableCents >= 0 ? "Net payable" : "Net refundable"} value={money(Math.abs(data.summary.salesTaxPayableCents))} note="Before filing adjustments"/></section><article className="bookloq-card tax-warning"><b>Professional review required</b><p>{data.disclaimer} Jurisdiction, eligibility, documentation, filing frequency and adjustments must be confirmed before relying on a filing position.</p></article><ProviderGate title="Tax filing is not connected" detail="BookLoQ will never claim a return was filed unless a verified filing integration returns an official successful confirmation."/></div>; }
function InventoryPanel({ data }: { data: BookLoQData }) { const inventory = data.statements.accounts.find((account) => account.systemKey === "inventory_asset")?.balanceCents ?? 0; const cogs = data.statements.profitAndLoss.cogsCents; const close = data.closeItems.find((item) => item.itemKey === "inventory"); return <div className="bookloq-content"><PageIntro eyebrow="INVENTORY ACCOUNTING" title="Connect product movement to the general ledger" copy="Adjustments require an approved reconciliation between POS, subledger, physical count, purchases and the ledger."/><section className="bookloq-kpis compact"><FinancialKpi label="Ledger inventory" value={money(inventory)} note="Inventory asset account"/><FinancialKpi label="Cost of goods sold" value={money(cogs)} note="Posted cost of sales"/><FinancialKpi label="Reconciliation" value={close ? label(close.status) : "Not started"} note={close?.blocker || "No blocker recorded"}/></section><ProviderGate title="SKU subledger not connected" detail="FIFO, weighted average, landed cost, shrinkage and physical-count adjustment remain unavailable until normalized SKU and inventory-movement records exist."/></div>; }
function AssetsPanel({ data }: { data: BookLoQData }) { const items = data.statements.accounts.filter((account) => account.systemKey === "fixed_assets" || account.systemKey === "loan_payable" || account.systemKey === "interest_expense"); return <div className="bookloq-content"><PageIntro eyebrow="ASSETS AND LOANS" title="Separate owned assets, principal and financing cost" copy="Loan principal and interest remain distinct so profit and debt are not distorted."/><DataTable headings={["Account", "Classification", "Explanation", "Balance"]} rows={items.map((account) => [`${account.code} · ${account.name}`, label(account.accountSubtype), account.plainLanguage, money(account.balanceCents)])}/><ProviderGate title="Schedules require agreements" detail="Depreciation and amortization schedules are not invented. Add verified purchase and lender agreements before BookLoQ generates recurring allocations."/></div>; }
function BudgetPanel({ data }: { data: BookLoQData }) { const actual = new Map(data.statements.accounts.map((account) => [account.code, account.balanceCents])); return <div className="bookloq-content"><PageIntro eyebrow="BUDGETING" title="Budget, committed, actual and forecast in one view" copy="Variance is calculated from the same posted ledger used by reports."/><DataTable headings={["Account", "Budget", "Actual", "Committed", "Forecast", "Variance"]} rows={data.budgets.map((budget) => { const value = actual.get(budget.accountCode) ?? 0; const variance = budget.accountType === "revenue" ? value - budget.budgetCents : budget.budgetCents - value; return [`${budget.accountCode} · ${budget.accountName}`, money(budget.budgetCents), money(value), money(budget.committedCents), money(budget.forecastCents), <span key="variance" className={variance < 0 ? "negative" : "positive"}>{money(variance)}</span>]; })}/></div>; }
function CashFlowPanel({ data }: { data: BookLoQData }) { const intel = data.cashIntelligence; return <div className="bookloq-content"><PageIntro eyebrow="CASH-FLOW INTELLIGENCE" title="See the cash point before it becomes urgent" copy="Confirmed obligations, probable receivables and purchasing capacity remain visibly separate."/><div className="bookloq-kpi-grid"><FinancialKpi label="30-day liquidity" value={money(intel.liquidity30Cents)} note="Dated inflows and outflows"/><FinancialKpi label="60-day liquidity" value={money(intel.liquidity60Cents)} note="Dated inflows and outflows"/><FinancialKpi label="Supplier purchasing capacity" value={money(intel.purchasingCapacityCents)} note="After confirmed obligations and safety reserve"/><FinancialKpi label="Liquidity risk" value={label(intel.risk)} note={intel.minimumCashDate ? `Low point ${money(intel.minimumCashCents)} on ${shortDate(intel.minimumCashDate)}` : "Verified cash source required"}/></div>{intel.warning && <article className="bookloq-card tax-warning"><b>Payment timing warning</b><p>{intel.warning}</p></article>}<article className="bookloq-card"><div className="cashflow-grid"><div className="cashflow-head"><span>Horizon</span><span>Confirmed</span><span>Probable</span><span>Estimated</span><span>Closing cash</span></div>{data.forecasts.map((forecast) => <div key={forecast.days}><span><b>{forecast.days === 365 ? "12 months" : `${forecast.days} days`}</b><small>{shortDate(forecast.endDate)}</small></span><span>{money(forecast.confirmedNetCents)}</span><span>{money(forecast.probableNetCents)}</span><span>{money(forecast.estimatedNetCents)}</span><strong className={forecast.closingCashCents < (data.settings?.cashSafetyThresholdCents ?? 0) ? "negative" : ""}>{money(forecast.closingCashCents)}</strong></div>)}</div></article><article className="bookloq-card tax-warning"><b>Calculation boundary</b><p>Opening cash {money(data.summary.currentCashCents)} plus dated confirmed payables and probable receivables. Purchasing capacity excludes probable income. Missing sources remain unavailable and no seasonal result is invented.</p></article></div>; }

function ReportsPanel({ data }: { data: BookLoQData }) { const [report, setReport] = useState<"pnl" | "balance" | "trial">("pnl"); const accounts = data.statements.accounts; const rows = report === "pnl" ? accounts.filter((account) => ["revenue", "expense"].includes(account.accountType)).map((account) => [account.code, account.name, label(account.accountType), money(account.balanceCents)]) : report === "balance" ? accounts.filter((account) => ["asset", "liability", "equity"].includes(account.accountType)).map((account) => [account.code, account.name, label(account.accountType), money(account.balanceCents)]) : accounts.map((account) => [account.code, account.name, money(account.debitCents), money(account.creditCents)]); return <div className="bookloq-content"><PageIntro eyebrow="FINANCIAL REPORTS" title="Accountant detail with owner-readable explanations" copy="Every total drills back to posted accounts. Report generation is timestamped and demonstration data remains labelled." action={<button onClick={() => downloadReport(report, rows)}>Export CSV</button>}/><div className="report-switch"><button className={report === "pnl" ? "active" : ""} onClick={() => setReport("pnl")}>Profit and loss</button><button className={report === "balance" ? "active" : ""} onClick={() => setReport("balance")}>Balance sheet</button><button className={report === "trial" ? "active" : ""} onClick={() => setReport("trial")}>Trial balance</button></div>{report === "pnl" && <ReportSummary items={[["Revenue", data.statements.profitAndLoss.revenueCents], ["Cost of goods sold", data.statements.profitAndLoss.cogsCents], ["Gross profit", data.statements.profitAndLoss.grossProfitCents], ["Total expenses", data.statements.profitAndLoss.expenseCents], ["Operating profit", data.statements.profitAndLoss.operatingProfitCents]]}/>} {report === "balance" && <ReportSummary items={[["Assets", data.statements.balanceSheet.assetCents], ["Liabilities", data.statements.balanceSheet.liabilityCents], ["Equity including earnings", data.statements.balanceSheet.equityCents]]}/>} {report === "trial" && <ReportSummary items={[["Total debits", data.statements.trialBalance.totalDebitCents], ["Total credits", data.statements.trialBalance.totalCreditCents], ["Difference", data.statements.trialBalance.totalDebitCents - data.statements.trialBalance.totalCreditCents]]}/>}<DataTable headings={report === "trial" ? ["Code", "Account", "Debits", "Credits"] : ["Code", "Account", "Type", "Balance"]} rows={rows}/><div className="export-gates"><button disabled title="A verified server-side PDF renderer is not configured.">PDF export unavailable</button><button disabled title="A verified XLSX renderer is not configured.">XLSX export unavailable</button><span>Generated {new Intl.DateTimeFormat("en-CA", { dateStyle: "medium", timeStyle: "short" }).format(new Date())}</span></div></div>; }
function ReportSummary({ items }: { items: [string, number][] }) { return <section className="report-summary">{items.map(([name, value]) => <div key={name}><span>{name}</span><b className={value < 0 ? "negative" : ""}>{money(value)}</b></div>)}</section>; }

function MonthEndPanel({ data, refresh, showNotice }: { data: BookLoQData; refresh: () => Promise<void>; showNotice: (message: string) => void }) { const complete = data.closeItems.filter((item) => item.status === "complete").length; const progress = data.closeItems.length ? complete / data.closeItems.length : 0; const period = data.periods[0]; const update = async (item: CloseItem, status: string) => { const response = await apiFetch("/api/v1/bookloq/actions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type: "month_end_status", itemId: item.id, status }) }); const body = await response.json(); if (!response.ok) { showNotice(body.error?.message ?? "Month-end item could not be updated"); return; } await refresh(); showNotice("Month-end progress updated"); }; const lock = async () => { if (!period) return; const response = await apiFetch("/api/v1/bookloq/actions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ type: "lock_period", periodId: period.id }) }); const body = await response.json(); if (!response.ok) { showNotice(body.error?.message ?? "Period could not be locked"); return; } await refresh(); showNotice("Accounting period locked and audited"); }; return <div className="bookloq-content"><PageIntro eyebrow="MONTH-END CLOSE" title={period ? `${period.label} close` : "No accounting period"} copy="Complete dependencies, review statements, approve the result, then lock the period." action={<button disabled={progress < 1 || period?.status === "locked"} title={progress < 1 ? "Complete every close item first." : "Lock this accounting period"} onClick={() => void lock()}>{period?.status === "locked" ? "Period locked" : "Lock period"}</button>}/><article className="bookloq-card close-progress"><div><span><b>{Math.round(progress * 100)}%</b><small>{complete} of {data.closeItems.length} controls complete</small></span><i><b style={{ width: `${progress * 100}%` }}/></i></div></article><article className="bookloq-card close-list">{data.closeItems.map((item) => <div key={item.id}><span className={`close-state ${item.status}`}>{item.status === "complete" ? "✓" : item.status === "blocked" ? "!" : "○"}</span><span><b>{item.title}</b><small>{item.blocker || `Due ${item.dueDate ? shortDate(item.dueDate) : "before lock"}`}</small></span><select value={item.status} onChange={(event) => void update(item, event.target.value)}><option value="not_started">Not started</option><option value="in_progress">In progress</option><option value="blocked">Blocked</option><option value="complete">Complete</option></select></div>)}</article></div>; }
function AccountantPanel({ data }: { data: BookLoQData }) { return <div className="bookloq-content"><PageIntro eyebrow="ACCOUNTANT PORTAL" title="Finance access without unrelated operational exposure" copy="The current account has the finance role and permissions shown below. Invitations remain unavailable until identity invitations and recent reauthentication are implemented."/><section className="bookloq-two"><article className="bookloq-card"><Header kicker="CURRENT ACCESS" title={label(data.role)}/><div className="permission-list">{data.permissions.map((permission) => <span key={permission}>✓ {label(permission)}</span>)}</div></article><ProviderGate title="Accountant invitations not yet available" detail="Vanteloq must verify recipient identity, role scope, expiry, acceptance and revocation before an invitation can be sent."/></section></div>; }
function AuditPanel({ data }: { data: BookLoQData }) { return <div className="bookloq-content"><PageIntro eyebrow="AUDIT TRAIL" title="Append-only history for sensitive finance events" copy="Posted journals, reversals, status changes, locks and exports are recorded with the trusted actor and organization scope."/><DataTable headings={["Time", "Action", "Resource", "Outcome", "Recorded detail"]} rows={data.audit.map((event) => [new Intl.DateTimeFormat("en-CA", { dateStyle: "medium", timeStyle: "short" }).format(new Date(event.createdAt * 1000)), label(event.action), `${label(event.resourceType)}${event.resourceId ? ` · ${event.resourceId.slice(-10)}` : ""}`, label(event.outcome), summarizeAudit(event.detailsJson)])}/></div>; }

function AssistantPanel({ data, createTask }: { data: BookLoQData; createTask: (seed: TaskSeed) => void }) { const prompts = ["What requires my attention today?", "Why does the bank not match my books?", "How much GST should I set aside?", "Can I afford to pay all supplier bills?", "Explain my balance sheet.", "Prepare a month-end checklist."]; const [question, setQuestion] = useState(prompts[0]); const [answer, setAnswer] = useState(() => assistantAnswer(prompts[0], data)); const ask = (value: string) => { setQuestion(value); setAnswer(assistantAnswer(value, data)); }; return <div className="bookloq-content"><PageIntro eyebrow="BOOKLOQ ASSISTANT" title="Plain-language answers grounded in the ledger" copy="The assistant explains deterministic calculations; it is never the source of truth for balances, tax or reconciliation."/><section className="assistant-layout"><aside>{prompts.map((prompt) => <button key={prompt} onClick={() => ask(prompt)}>{prompt}</button>)}</aside><article className="bookloq-card assistant-card"><form onSubmit={(event) => { event.preventDefault(); ask(question); }}><input value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Ask about verified BookLoQ data"/><button>Ask</button></form><div><span className={`confidence ${answer.confidence}`}>{answer.confidence} confidence</span><h3>{answer.title}</h3><p>{answer.answer}</p><dl><dt>Calculation</dt><dd>{answer.calculation}</dd><dt>Supporting records</dt><dd>{answer.supporting.join(" · ") || "No supporting record available"}</dd><dt>Missing information</dt><dd>{answer.missing || "None material for this answer"}</dd></dl>{answer.action && <button className="bookloq-primary" onClick={() => createTask({ title: answer.action!, detail: `${answer.answer} Calculation: ${answer.calculation}`, priority: "medium", expectedImpact: "Review BookLoQ supporting records", sourceType: "alert", sourceRef: "bookloq-assistant" })}>Create recommended task</button>}</div></article></section></div>; }

function SettingsPanel({ data }: { data: BookLoQData }) { return <div className="bookloq-content"><PageIntro eyebrow="BOOKLOQ SETTINGS" title="Accounting policy, permissions and provider controls" copy="Sensitive configuration remains server-authorized and tenant-scoped."/><section className="bookloq-two"><article className="bookloq-card settings-list"><Header kicker="ACCOUNTING PROFILE" title={data.organization.name}/><LineText name="Base currency" value={data.settings?.baseCurrency ?? data.organization.currency}/><LineText name="Accounting basis" value={label(data.settings?.accountingBasis ?? "not configured")}/><LineText name="Jurisdiction" value={`${data.settings?.countryCode ?? "CA"}-${data.settings?.provinceCode ?? "AB"}`}/><LineText name="Cash safety threshold" value={money(data.settings?.cashSafetyThresholdCents ?? 0)}/><LineText name="Data mode" value={label(data.settings?.dataMode ?? "live")}/></article><article className="bookloq-card settings-list"><Header kicker="INTEGRATION STATUS" title="Financial providers"/>{Object.entries(data.integrations).map(([name, status]) => <LineText key={name} name={label(name)} value={label(status)}/>)}</article></section><ProviderGate title="Configuration changes are guarded" detail="Banking, tax, payroll, export and period permissions are separate. Secrets are never exposed to browser code, and real integrations require verified server-side token storage."/></div>; }

function JournalComposer({ data, close, saved }: { data: BookLoQData; close: () => void; saved: () => Promise<void> }) { const accounts = data.statements.accounts; const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const [memo, setMemo] = useState(""); const [debit, setDebit] = useState(accounts.find((account) => account.normalBalance === "debit")?.id ?? ""); const [credit, setCredit] = useState(accounts.find((account) => account.normalBalance === "credit")?.id ?? ""); const [amount, setAmount] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const submit = async (event: FormEvent) => { event.preventDefault(); const cents = parseMoney(amount); if (!cents || !debit || !credit || debit === credit) { setError("Choose two different accounts and enter a positive amount with no more than two decimals."); return; } setBusy(true); const response = await apiFetch("/api/v1/bookloq/journals", { method: "POST", headers: { "Content-Type": "application/json", "Idempotency-Key": crypto.randomUUID() }, body: JSON.stringify({ entryDate: date, memo, currency: data.organization.currency, lines: [{ accountId: debit, description: memo, debitCents: cents, creditCents: 0, locationRef: "all" }, { accountId: credit, description: memo, debitCents: 0, creditCents: cents, locationRef: "all" }] }) }); const body = await response.json(); if (!response.ok) { setError(body.error?.message ?? "Journal could not be posted."); setBusy(false); return; } await saved(); }; return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-label="Create balanced journal"><form className="bookloq-journal-form" onSubmit={submit}><div><span><small>BOOKLOQ GENERAL JOURNAL</small><h3>Post a balanced entry</h3></span><button type="button" onClick={close}>×</button></div><label>Entry date<input type="date" value={date} onChange={(event) => setDate(event.target.value)} required/></label><label>Explanation<textarea value={memo} onChange={(event) => setMemo(event.target.value)} maxLength={1000} required placeholder="Why this entry is required and what supports it"/></label><div className="journal-line"><span>Debit</span><select value={debit} onChange={(event) => setDebit(event.target.value)}>{accounts.map((account) => <option value={account.id} key={account.id}>{account.code} · {account.name}</option>)}</select><input inputMode="decimal" value={amount} onChange={(event) => setAmount(event.target.value)} placeholder="0.00"/></div><div className="journal-line"><span>Credit</span><select value={credit} onChange={(event) => setCredit(event.target.value)}>{accounts.map((account) => <option value={account.id} key={account.id}>{account.code} · {account.name}</option>)}</select><input value={amount} readOnly aria-label="Credit amount"/></div><p className="journal-balance">Debits {money(parseMoney(amount) ?? 0)} · Credits {money(parseMoney(amount) ?? 0)} · Difference {money(0)}</p>{error && <p className="bookloq-form-error">{error}</p>}<footer><button type="button" onClick={close}>Cancel</button><button className="bookloq-primary" disabled={busy}>{busy ? "Posting…" : "Post balanced journal"}</button></footer></form></div>; }

function PageIntro({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: ReactNode }) { return <section className="bookloq-page-intro"><div><p>{eyebrow}</p><h3>{title}</h3><span>{copy}</span></div>{action}</section>; }
function ProviderGate({ title, detail }: { title: string; detail: string }) { return <article className="bookloq-provider-gate"><span aria-hidden="true">⛨</span><div><b>{title}</b><p>{detail}</p></div><strong className="provider-state">Not connected</strong></article>; }
function DataTable({ headings, rows }: { headings: string[]; rows: ReactNode[][] }) { return <article className="bookloq-card bookloq-generic-table"><div className="generic-row generic-head" style={{ gridTemplateColumns: `repeat(${headings.length}, minmax(110px, 1fr))` }}>{headings.map((heading) => <span key={heading}>{heading}</span>)}</div>{rows.map((row, index) => <div className="generic-row" key={index} style={{ gridTemplateColumns: `repeat(${headings.length}, minmax(110px, 1fr))` }}>{row.map((cell, cellIndex) => <span key={cellIndex}>{cell}</span>)}</div>)}{!rows.length && <EmptyLine text="No source-backed records exist for this view."/>}</article>; }
function RecordDrawer({ title, rows, close }: { title: string; rows: [string, string][]; close: () => void }) { return <div className="bookloq-record-drawer"><div><span><small>SUPPORTING RECORD</small><h3>{title}</h3></span><button onClick={close}>×</button></div><dl>{rows.map(([name, value]) => <span key={name}><dt>{name}</dt><dd>{value}</dd></span>)}</dl></div>; }
function Line({ label: name, value, total = false }: { label: string; value: number; total?: boolean }) { return <div className={total ? "bridge-total" : ""}><span>{name}</span><b className={value < 0 ? "negative" : ""}>{money(value)}</b></div>; }
function LineText({ name, value }: { name: string; value: string }) { return <div className="line-text"><span>{name}</span><b>{value}</b></div>; }

function sectionIcon(section: Section): string { if (["Overview", "Reports"].includes(section)) return "▦"; if (["Banking", "Cash Flow", "Reconciliation"].includes(section)) return "◇"; if (["Bills", "Expenses", "Sales", "Invoicing"].includes(section)) return "$"; if (["Journal Entries", "Chart of Accounts", "Audit Trail"].includes(section)) return "≡"; if (section === "BookLoQ Assistant") return "✦"; return "·"; }
function parseMoney(value: string): number | null { const normalized = value.trim().replaceAll(",", ""); const match = /^(\d{1,12})(?:\.(\d{0,2}))?$/.exec(normalized); if (!match) return null; const cents = Number(match[1]) * 100 + Number((match[2] ?? "").padEnd(2, "0")); return Number.isSafeInteger(cents) && cents > 0 ? cents : null; }
function summarizeAudit(value: string): string { try { const parsed = JSON.parse(value) as Record<string, unknown>; return Object.entries(parsed).slice(0, 3).map(([key, item]) => `${label(key)}: ${String(item)}`).join(" · ") || "No additional detail"; } catch { return "Recorded event"; } }
function downloadCsv(file: string, headings: string[], rows: (string | number)[][]) { const escape = (value: string | number) => `"${String(value).replaceAll('"', '""')}"`; const csv = [headings.map(escape).join(","), ...rows.map((row) => row.map(escape).join(","))].join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = file; anchor.click(); URL.revokeObjectURL(url); }
function downloadTransactions(rows: Transaction[]) { downloadCsv("bookloq-transactions.csv", ["Posting date", "Description", "Original description", "Amount cents", "Currency", "Account", "Source", "External ID", "Categorization", "Reconciliation", "Confidence basis points"], rows.map((item) => [item.postingDate, item.description, item.originalDescription, item.amountCents, item.currency, item.accountName ?? "", item.sourceSystem, item.externalSourceId, item.categorizationStatus, item.reconciliationStatus, item.confidenceBasisPoints])); }
function downloadReport(report: string, rows: ReactNode[][]) { downloadCsv(`bookloq-${report}-${new Date().toISOString().slice(0, 10)}.csv`, ["Code", "Account", "Classification", "Amount"], rows.map((row) => row.map((value) => typeof value === "string" || typeof value === "number" ? value : "Rendered value"))); }

function assistantAnswer(question: string, data: BookLoQData) {
  const q = question.toLowerCase();
  const difference = (data.summary.bankBalanceCents ?? data.summary.bookBalanceCents) - data.summary.bookBalanceCents;
  if (q.includes("bank") && q.includes("match")) return {
    title: "The bank is below the books by " + money(Math.abs(difference)),
    answer: difference === 0 ? "The stored bank and book balances agree." : `The stored bank balance is ${money(Math.abs(difference))} ${difference < 0 ? "below" : "above"} the posted cash ledger. The open reconciliation links this to an unmatched settlement timing item.`,
    calculation: `${money(data.summary.bankBalanceCents)} bank − ${money(data.summary.bookBalanceCents)} books = ${money(difference)}`,
    supporting: data.reconciliations.map((item) => `${item.accountCode} reconciliation ${item.id.slice(-8)}`),
    missing: "A live bank feed and statement image are not connected.", confidence: "high" as const, action: "Resolve the bank-to-book difference",
  };
  if (q.includes("gst") || q.includes("hst") || q.includes("tax")) {
    const collected = data.statements.accounts.find((account) => account.systemKey === "gst_collected")?.balanceCents ?? 0;
    const recoverable = data.statements.accounts.find((account) => account.systemKey === "gst_recoverable")?.balanceCents ?? 0;
    return {
      title: `${money(Math.abs(collected - recoverable))} estimated net GST position`,
      answer: `Posted GST collected is ${money(collected)} and posted recoverable GST is ${money(recoverable)}. This is a working position, not a filed return.`,
      calculation: `${money(collected)} collected − ${money(recoverable)} recoverable = ${money(collected - recoverable)}`,
      supporting: ["2100 GST collected", "1150 GST recoverable"],
      missing: "Filing adjustments, documentation eligibility and official confirmation.", confidence: "high" as const, action: "Review GST working papers",
    };
  }
  if (q.includes("afford") || q.includes("supplier bill")) return {
    title: data.summary.availableCashCents >= 0 ? "Confirmed 30-day bills fit within posted cash" : "Posted cash does not cover confirmed 30-day bills",
    answer: `Posted cash is ${money(data.summary.currentCashCents)}. After confirmed bills due within 30 days, available cash is ${money(data.summary.availableCashCents)} before probable collections and unmodeled obligations.`,
    calculation: `${money(data.summary.currentCashCents)} cash − confirmed 30-day bills = ${money(data.summary.availableCashCents)}`,
    supporting: data.bills.map((bill) => `${bill.billNumber} ${money(bill.totalCents - bill.paidCents)}`),
    missing: "Live bank availability, unentered bills, payroll, card due dates and tax payment schedules.", confidence: "medium" as const, action: "Review the 30-day payment plan",
  };
  if (q.includes("balance sheet") || q.includes("explain")) return {
    title: "Assets, liabilities and equity remain balanced through double entry",
    answer: `Assets are ${money(data.statements.balanceSheet.assetCents)}, liabilities are ${money(data.statements.balanceSheet.liabilityCents)}, and equity including current earnings is ${money(data.statements.balanceSheet.equityCents)}.`,
    calculation: `${money(data.statements.balanceSheet.assetCents)} assets − ${money(data.statements.balanceSheet.liabilityCents)} liabilities = ${money(data.statements.balanceSheet.equityCents)} equity`,
    supporting: data.statements.accounts.filter((account) => ["asset", "liability", "equity"].includes(account.accountType)).map((account) => `${account.code} ${account.name}`),
    missing: "Unrecorded assets, liabilities or adjustments cannot be inferred.", confidence: "high" as const, action: null,
  };
  if (q.includes("month-end") || q.includes("checklist")) {
    const incomplete = data.closeItems.filter((item) => item.status !== "complete");
    return {
      title: `${incomplete.length} month-end controls remain`,
      answer: incomplete.map((item) => `${item.title}: ${label(item.status)}`).join("; ") || "Every recorded close control is complete.",
      calculation: `${data.closeItems.length - incomplete.length} complete ÷ ${data.closeItems.length} total = ${Math.round(data.summary.monthEndCompletionRate * 100)}%`,
      supporting: incomplete.map((item) => item.itemKey),
      missing: incomplete.find((item) => item.blocker)?.blocker ?? "No recorded blocker", confidence: "high" as const, action: incomplete.length ? "Complete the remaining month-end controls" : null,
    };
  }
  const open = data.alerts.filter((alert) => alert.status === "open");
  return {
    title: `${open.length} financial items require review`,
    answer: open.map((alert) => `${alert.title}: ${alert.recommendedAction}`).join(" ") || "No open BookLoQ alert currently requires action.",
    calculation: `${open.filter((alert) => alert.severity === "critical").length} critical + ${open.filter((alert) => alert.severity === "attention").length} attention + ${open.filter((alert) => alert.severity === "opportunity").length} opportunities`,
    supporting: open.flatMap((alert) => parseJsonList(alert.supportingRecordsJson)),
    missing: "No additional cause is inferred beyond the linked records.", confidence: "high" as const, action: open[0]?.recommendedAction ?? null,
  };
}
